{
    var angle = 2 * Math.PI * i / segments;
    coords[i] = new Coordinate(
        cx + radiusMeters * Math.Cos(angle),   // east/west offset in meters
        cy + radiusMeters * Math.Sin(angle));  // north/south offset in meters
}
